// A fictional animation-production puzzle, not real employment advice or a scheduling service.
const id='labor';const W=(zh,en,ja)=>({zh,en,ja});
const JOBS=[{shot:0,step:0,duration:10},{shot:0,step:1,duration:12},{shot:0,step:2,duration:8},{shot:1,step:0,duration:10},{shot:1,step:1,duration:12},{shot:1,step:2,duration:8}].map(Object.freeze);
const breaks=[{start:20,end:26},{start:0,end:10},{start:0,end:8}],names=[W('草稿','Rough','ラフ'),W('動作','Motion','動き'),W('上色','Color','彩色')];
const createSchedule=()=>JOBS.map(()=>({artist:0,start:0}));
const overlap=(a,b)=>a.start<b.end&&b.start<a.end;
function evaluate(schedule){if(!Array.isArray(schedule)||schedule.length!==6||schedule.some(j=>!j||!Number.isInteger(j.artist)||j.artist<0||j.artist>2||!Number.isFinite(j.start)||j.start<0||j.start>42))return {ok:false,reason:'range',loads:[0,0,0],validJobs:0};const jobs=schedule.map((j,i)=>({...j,end:j.start+JOBS[i].duration})),loads=[0,0,0];jobs.forEach((j,i)=>loads[j.artist]+=JOBS[i].duration);
 for(const j of jobs)if(j.end>50)return {ok:false,reason:'deadline',loads,validJobs:0};
 for(let i=0;i<6;i++)if(JOBS[i].step&&jobs[i].start<jobs[i-1].end)return {ok:false,reason:'dependency',loads,validJobs:i};
 for(let i=0;i<6;i++){if(overlap(jobs[i],breaks[jobs[i].artist]))return {ok:false,reason:'break',loads,validJobs:i};for(let j=i+1;j<6;j++)if(jobs[i].artist===jobs[j].artist&&overlap(jobs[i],jobs[j]))return {ok:false,reason:'overlap',loads,validJobs:i};}
 if(loads.some(n=>n>28))return {ok:false,reason:'load',loads,validJobs:0};return {ok:true,reason:'ok',loads,validJobs:6,finish:Math.max(...jobs.map(j=>j.end))};}
